import{_ as t}from"./chunks/CreateLoginPage.B2-9vp7z.js";import{_ as r}from"./chunks/Admin_eperson_supervisor.BV3hwld1.js";import{_ as s,c as o,a2 as a,o as i}from"./chunks/framework.CoXjB5sU.js";const n="/assets/Admin_sidebar_access_control.CSROhgZI.png",m="/assets/Admin_group_create.PV4_6SHO.png",u="/assets/Admin_group_new_community.BT5AmpBH.png",l="/assets/Admin_eperson_create.DuONvcaY.png",_=JSON.parse('{"title":"Creating users and groups","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/installation/user-and-group-generation.md","filePath":"doc/guides/installation/user-and-group-generation.md"}'),p={name:"doc/guides/installation/user-and-group-generation.md"};function g(c,e,h,d,f,b){return i(),o("div",null,e[0]||(e[0]=[a('<h1 id="creating-users-and-groups" tabindex="-1">Creating users and groups <a class="header-anchor" href="#creating-users-and-groups" aria-label="Permalink to &quot;Creating users and groups&quot;">​</a></h1><p>Content published in Browse is public, but Create is a private workspace: every user needs an account. The administrator creates the accounts and organises them in <strong>user groups</strong>.</p><p>A user group usually matches a research group, and it defines what its members can do:</p><ul><li><strong>Publishing community</strong>: members can publish from Create into this <a href="./publishing-endpoints-definition.html">Browse community</a>.</li><li><strong>Organization</strong>: members get it as default affiliation on their Browse profile.</li><li><strong>Ownership in Create</strong>: every user has a <strong>main group</strong>. Projects and calculations created in Create belong to it.</li><li><strong>Supervision</strong>: members of a group can be marked as <strong>supervisors</strong> of it. Supervisors can browse the Create content of the group members and publish it on their behalf, see <a href="./../usage/supervise-feature.html">Supervise users</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create the <a href="./publishing-endpoints-definition.html">publication communities</a> first: you will link each group to its community when creating it.</p></div><h2 id="administrator-login" tabindex="-1">Administrator login <a class="header-anchor" href="#administrator-login" aria-label="Permalink to &quot;Administrator login&quot;">​</a></h2><p>Open Browse (<code>https://&lt;hostname&gt;/browse</code>) and click <em>Log in</em> in the user menu at the top right. You are taken to the login page, common to every module. Enter the administrator email and password set <a href="./required-steps.html#administrator-account-settings">during the installation</a>.</p><p><img src="'+t+'" alt="Login page"></p><p>If you forgot the password, use <em>Forgot your password?</em> on the same page.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The administrator account manages the platform. To work in Create, the administrator should use a separate, regular user account.</p></div><p>Once logged in, the management sidebar appears on the left side of Browse. Hover over it to expand it. Users and groups are managed under <em>Access Control</em>:</p><ul><li><em>People</em>: create, edit and delete user accounts.</li><li><em>Groups</em>: create, edit and delete user groups.</li></ul><p><img src="'+n+'" alt="Access Control options of the management sidebar"></p><h2 id="creating-groups" tabindex="-1">Creating groups <a class="header-anchor" href="#creating-groups" aria-label="Permalink to &quot;Creating groups&quot;">​</a></h2><p>Click <em>Access Control</em> &gt; <em>Groups</em> and then <em>Add group</em>. Fill in the form:</p><ul><li><strong>Group name</strong>: a short identifier, e.g. <em>curie_group</em>.</li><li><strong>Description</strong>: optional.</li><li><strong>Publishing community</strong>: search the community and click it in the list. Without one, the members can only publish into communities they administer directly.</li><li><strong>Organization (default affiliation)</strong>: preselected when the repository has a single organization. Click <em>Change institution</em> to pick another one.</li></ul><p><img src="'+m+'" alt="Create group form"></p><p>Click <em>Save</em> to create the group.</p><p>If the community doesn&#39;t exist yet, click <em>New community</em> below the community list. Enter its name and parent community (or leave <em>None</em> for a top-level one) and click <em>Create</em>: the new community is created and selected.</p><p><img src="'+u+'" alt="New community created from the group form"></p><p>You can change the publishing community of a group at any time from the same form (<em>Access Control</em> &gt; <em>Groups</em>, edit button of the group). Its members gain or lose the right to publish there at once.</p><h2 id="creating-users" tabindex="-1">Creating users <a class="header-anchor" href="#creating-users" aria-label="Permalink to &quot;Creating users&quot;">​</a></h2><p>Click <em>Access Control</em> &gt; <em>People</em> and then <em>Add EPerson</em>. Fill in the form:</p><ul><li><strong>First name</strong>, <strong>Last name</strong> and <strong>Email</strong>. The email is the login name. The username is derived from the name.</li><li><strong>Password delivery</strong>: <em>Send password link by email</em> emails the user a link to set the password. <em>Generate random password</em> sets a password that you must give to the user.</li><li><strong>Can log in</strong>: keep it checked.</li><li><strong>Belongs to group(s)</strong>: search the user&#39;s groups under <em>All available groups</em> and add them with the <kbd>+</kbd> button. Then select the <strong>Main group</strong> among them (required).</li><li><strong>Communities user can publish into</strong>: read-only. It shows the publishing communities the user gets through their groups.</li></ul><p><img src="'+l+'" alt="Create EPerson form"></p><p>Click <em>Create</em>. With <em>Send password link by email</em>, the user receives an email to set the password and can then log in to Create and Browse.</p><p>To edit or delete an account later, go to <em>Access Control</em> &gt; <em>People</em>, search the user and use the edit or delete buttons of its row.</p><h2 id="setting-supervisors" tabindex="-1">Setting supervisors <a class="header-anchor" href="#setting-supervisors" aria-label="Permalink to &quot;Setting supervisors&quot;">​</a></h2><p>To make a user supervisor of one of their groups, edit the user (<em>Access Control</em> &gt; <em>People</em>) and check the <em>Supervisor</em> column of that group under <em>Current member groups</em>. Then click <em>Save</em>. In this example Hassan Sosa supervises the <em>lamarr_group</em> members:</p><p><img src="'+r+'" alt="Supervisor checkbox of a group membership"></p><p>The user must belong to the group to supervise it. See <a href="./../usage/supervise-feature.html">Supervise users</a> for what supervisors can do in Create.</p>',31)]))}const w=s(p,[["render",g]]);export{_ as __pageData,w as default};
